INSERT INTO LIVROS_NOMES (NOME, CATALOGO_ID, ESTADO, MOTIVO, CRIADO_EM) SELECT X.TITULO, {{catId}}, 'OK', 'Decidido pela pessoa', DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s') FROM LIVROS_INDICADOS X WHERE X.ID = {{id}} ON DUPLICATE KEY UPDATE CATALOGO_ID = VALUES(CATALOGO_ID), ESTADO = 'OK', MOTIVO = VALUES(MOTIVO)